    if (N == 0) return 1;
    return permute(A, 0, new boolean[N]);
}

private static int permute(int[] A, int start, boolean[] used) {
    if (start == A.length) return 1;
    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (used[i] || (start > 0 && !isPerfectSquare(A[start - 1] + A[i]))) continue;
        used[i] = true;
        count += permute(A, start + 1, used);
        used[i] = false;
    }
    return count;
}

private static boolean isPerfectSquare(int num) {
