}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    Stack<Integer> stack = new Stack<>();
    for (int i = 0; i <= heights.length; i++) {
        while (!stack.isEmpty() && (i == heights.length || heights[stack.peek()] >= heights[i])) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int r = 0, c = 0;

    for (int i = 0; i < m * n; i++) {
        result[i] = mat[r][c];
        if ((r + c) % 2 == 0) {
            if (c == n - 1) {
                r++;
            } else if (r == 0) {
                c++;
            } else {
                r--;
                c++;
            }
        } else {
            if (r == m - 1) {
                c++;
            } else if (c == 0) {
                r++;
            } else {
                r++;
                c--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i;
    // Find the first digit that is smaller than the digit next to it
    for (i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }
    // If no such digit is found, return -1 (not possible to rearrange)
    if (i == -1) {
        return -1;
    }
    // Find the smallest digit on the right side of (i-th digit) which is greater than digits[i]
    int minIndex = i + 1;
    for (int j = i + 2; j < digits.length; j++) {
        if (digits[j] > digits[i] && digits[j] < digits[minIndex]) {
            minIndex = j;
        }
    }
    // Swap the above found smallest digit with digits[i]
    char temp = digits[i];
    digits[i] = digits[minIndex];
    digits[minIndex] = temp;
    // Sort the digits after the (i-th digit) in ascending order
    Arrays.sort(digits, i + 1, digits.length);
    // Convert the digits back to number
    return Integer.parseInt(new String(digits));
}

